// ========== Module 7: 差分方程 ==========

const ca_07_01: Topic = {
  id: 'ca-07-01',
  moduleId: 'pe-exam-303-calculus',
  title: '差分方程',
  description: '差分的概念、一阶差分方程、二阶常系数差分方程',
  content: `# 差分方程

<Glossary terms="%5B%7B%22term%22%3A%22%E5%B7%AE%E5%88%86%22%2C%22english%22%3A%22Difference%22%2C%22definition%22%3A%22%CE%94y%E2%82%99%3Dy%E2%82%99%E2%82%8A%E2%82%81-y%E2%82%99%22%7D%2C%7B%22term%22%3A%22%E5%B7%AE%E5%88%86%E6%96%B9%E7%A8%8B%22%2C%22english%22%3A%22Difference%20Equation%22%2C%22definition%22%3A%22%E5%90%AB%E6%9C%89%E6%9C%AA%E7%9F%A5%E5%BA%8F%E5%88%97%E5%B7%AE%E5%88%86%E7%9A%84%E6%96%B9%E7%A8%8B%22%7D%5D" />

## 考情分析

- **分值**：303数学三满分150分中，差分方程约4–5分，多出现在填空题或计算题的最后一小问
- **题型**：填空题（直接求通解/特解）、计算题（建立差分方程模型并求解）
- **考频**：★ 数三特有内容。出现频率不高，但题型固定、套路清晰，属于“记住公式就稳拿分”的送分点

## 一、概念与直观

### 1. 差分：离散世界里的“导数”

导数描述连续变化；但人口按年统计、存款按月计息、数列本身只在整数点上有意义时，自变量不再连续。这时用“相邻两项之差”刻画变化率，这就是**差分**。

给定数列 y₀, y₁, y₂, …, yₙ, …（也可视为定义在非负整数上的函数 y=y(n)）：

- **一阶向前差分**：Δyₙ = yₙ₊₁ - yₙ
- **二阶差分**：Δ²yₙ = Δ(Δyₙ) = Δyₙ₊₁ - Δyₙ = yₙ₊₂ - 2yₙ₊₁ + yₙ
- 一般地，k 阶差分由 k-1 阶差分再作差得到

直观对照：Δ 相当于 d/dn，Δ² 相当于 d²/dn²。连续情形求导“降次”，离散情形作差“错位相减”。注意 Δyₙ 是“从 n 到 n+1 的增量”，不要与 yₙ - yₙ₋₁ 混淆（后者下标平移了 1）。

### 2. 差分方程

含有未知数列 yₙ 及其差分 Δyₙ, Δ²yₙ, … 的方程，称为差分方程。由于差分总可以展开成 yₙ₊₁, yₙ, yₙ₋₁, … 的组合，考场上更常用的写法是**超前（移位）形式**，例如 yₙ₊₁ + a yₙ = f(n)。

- **阶**：方程中未知数列下标最大值与最小值之差（或最高阶差分的阶数）。yₙ₊₁ - 2yₙ = 3 是一阶；yₙ₊₂ - 3yₙ₊₁ + 2yₙ = 0 是二阶
- **齐次与非齐次**：右端 f(n)≡0 时称齐次；否则称非齐次
- **线性**：未知数列及其移位项都是一次幂，且系数只与 n 有关（系数为常数时称常系数）
- **解**：代入后对一切所考虑的 n 成立的数列
- **通解**：含任意常数的解，常数个数等于阶数；**特解**：由初值定出常数后的解

### 3. 与微分方程的对照

| 微分方程 | 差分方程 |
|---------|---------|
| y′ + a y = f(x) | yₙ₊₁ + a yₙ = f(n) |
| 齐次解为指数函数 C e^{λx} | 齐次解为几何数列 C·(-a)ⁿ |
| 特征根法解高阶齐次 | 特征方程求根后写 λⁿ |
| 非齐次通解=齐次通解+一个特解 | 完全相同 |
| 初值 y(x₀)=y₀ | 初值 y₀（二阶则 y₀, y₁） |

真正要换的只是“解的外形”和特解设定的撞根判断，线性结构的骨架是同一套。

差分方程的应用几乎都是“离散计数”场景：人口按年增长、存款按月计息、商品价格按期调整、细胞按代繁殖、设备按年折旧。建模时先确定时间步长（一年还是一月），再写出相邻两期的增量关系，最后翻译成超前方程。时间步长一旦选定，整个数列的下标含义就固定了，后面求解不能中途改换。

## 二、核心定理与公式（含使用条件）

### 1. 一阶线性常系数差分方程

标准形式：

**yₙ₊₁ + a yₙ = f(n)**，a 为常数

**齐次通解**（f(n)=0）：

yₙ = C·(-a)ⁿ

使用条件：a 为常数；C 由初值确定。注意底数是 **-a** 而不是 a。例如 yₙ₊₁ - 2yₙ = 0 中 a=-2，通解 yₙ = C·2ⁿ。

**非齐次通解结构**：

yₙ = C·(-a)ⁿ + yₙ*

其中 yₙ* 只需是**任意一个**特解。这是线性方程的叠加原理，与微分方程同构。

### 2. 非齐次特解的待定系数法（最关键的是“撞根”判断）

对 yₙ₊₁ + a yₙ = f(n)：

**(1) f(n) = b（常数）**

- 若 1+a ≠ 0，设 yₙ* = A，代入得 A = b/(1+a)
- 若 1+a = 0（即 a = -1），方程变为 yₙ₊₁ - yₙ = b，设 yₙ* = A n，得 A = b

**(2) f(n) = Pₖ(n)（k 次多项式）**

- 若 1+a ≠ 0，设 yₙ* = Qₖ(n)（与 Pₖ 同次的一般多项式）
- 若 1+a = 0，设 yₙ* = n·Qₖ(n)

**(3) f(n) = b·dⁿ（d ≠ 0）**

- 若 d+a ≠ 0，设 yₙ* = A·dⁿ
- 若 d+a = 0，设 yₙ* = A n dⁿ

记忆口诀：右端自由项若与齐次解“撞形式”，特解一律多乘一个 n。这与微分方程中“右端是特征根对应项时乘 x”完全平行。

### 3. 二阶常系数线性差分方程

标准形式：

**yₙ₊₂ + p yₙ₊₁ + q yₙ = f(n)**，p, q 为常数且 q ≠ 0

**齐次方程**的特征方程：

λ² + p λ + q = 0

设特征根为 λ₁, λ₂，则齐次通解：

1. 两不等实根：yₙ = C₁·λ₁ⁿ + C₂·λ₂ⁿ
2. 两相等实根 λ：yₙ = (C₁ + C₂ n)·λⁿ
3. 共轭复根：写成实解 yₙ = rⁿ (C₁ cos nθ + C₂ sin nθ)，其中 r = √q（q>0 时），θ 为幅角

**非齐次**：通解 = 齐次通解 + 一个特解。特解仍用待定系数，规则看“d（或 1）是否为特征根”：

- f(n) = Pₖ(n)：1 不是特征根 → 设 Qₖ(n)；是单根 → 设 n Qₖ(n)；是重根 → 设 n² Qₖ(n)
- f(n) = b dⁿ：d 不是特征根 → 设 A dⁿ；是单根 → 设 A n dⁿ；是重根 → 设 A n² dⁿ

使用条件：p, q 常数且 q ≠ 0；待定系数法适用于 f(n) 为多项式、指数，或它们的乘积。最终答案必须写成实数形式，不能留虚数单位。若 f(n) 是多项式与指数的乘积，例如 n·dⁿ，则综合两条规则：先判断 d 是否为特征根决定是否乘 n，再按多项式次数设满低次项。

### 4. 递推公式法（备选工具）

一阶方程也可以不用“特解公式”，直接用累加法：由 yₙ₊₁ = -a yₙ + f(n) 逐项递推，或写成

yₙ = (-a)ⁿ y₀ + Σ_{k=0}^{n-1} (-a)^{n-1-k} f(k)

当 f(k) 是等比或等差时，右边的和可以求出闭式。这个公式说明：零输入响应就是齐次解，零状态响应就是特解的一种具体构造。考研若给递推式而不强调“解差分方程”，用递推找规律再归纳也是合法路径，但最后仍应写成通解形式以保步骤分。

### 5. 初值与任意常数

一阶通解含 1 个任意常数，需 1 个初值（通常给 y₀）；二阶需 2 个初值（y₀, y₁）。定完常数后应回代检验前两步递推。若题目给的是 y₁, y₂ 而不是 y₀, y₁，可先保留通解，把 n=1, n=2 代入解方程组，不必强行“翻译”下标。

## 三、计算方法与步骤

求解常系数线性差分方程的固定流程：

1. **化标准形**。移项、除以系数，整理成 yₙ₊₁ + a yₙ = f(n) 或 yₙ₊₂ + p yₙ₊₁ + q yₙ = f(n)，让最高移位项系数为 1，右端的 f(n) 单独放在一边。
2. **解对应齐次方程**。一阶直接写 C·(-a)ⁿ；二阶先写特征方程 λ² + p λ + q = 0，按根的情况写齐次通解。
3. **设特解**。按 f(n) 的类型（常数 / 多项式 / 指数）以及“是否撞根”，选择 A、A n、Qₖ(n)、n Qₖ(n)、A dⁿ、A n dⁿ 等形式。设得不够一般，会解出矛盾或漏解。
4. **代入定系数**。把特解形式代入原方程，比较 n 的同次幂系数（或同指数因子），解出待定参数。特解只需找一个。
5. **写出通解**：齐次通解 + 特解。
6. **代初值定常数**。用 y₀（及 y₁）列线性方程组，解出 C（或 C₁, C₂）。
7. **回代检验**。至少验算 n=0、n=1 两步，重点查移位符号与正负号。

若考“应用建模”，先写清“n 时刻到 n+1 时刻的增量关系”即 Δyₙ = …，再化为标准形，后续同上。

## 四、典型例题精讲

**例1** 求差分方程 yₙ₊₁ - 2yₙ = 3 的通解。

解：已是标准形 yₙ₊₁ + a yₙ = f(n)，其中 a = -2，f(n) = 3。

第一步，求齐次通解。yₙ₊₁ - 2yₙ = 0 的通解为 yₙ = C·(-a)ⁿ = C·2ⁿ。

第二步，求一个特解。f(n)=3 为常数，且 1+a = 1-2 = -1 ≠ 0，故设 yₙ* = A（常数）。代入原方程：

A - 2A = 3，即 -A = 3，得 A = -3，所以 yₙ* = -3。

因此通解为

**yₙ = C·2ⁿ - 3**（C 为任意常数）。

检验：取 C=1，则 yₙ = 2ⁿ - 3。yₙ₊₁ - 2yₙ = (2ⁿ⁺¹ - 3) - 2(2ⁿ - 3) = 2·2ⁿ - 3 - 2·2ⁿ + 6 = 3，与右端一致。

**例2** 求 yₙ₊₁ + yₙ = 2n 满足 y₀ = 0 的特解。

解：这里 a = 1，f(n) = 2n 是一次多项式。因 1+a = 2 ≠ 0，设特解 yₙ* = A n + B。

代入 yₙ₊₁ + yₙ = 2n：

[A(n+1) + B] + [A n + B] = 2n
2A n + (A + 2B) = 2n

比较系数得方程组：2A = 2，A + 2B = 0。解得 A = 1，B = -1/2。故特解 yₙ* = n - 1/2。

齐次方程 yₙ₊₁ + yₙ = 0 的通解为 yₙ = C·(-1)ⁿ，所以通解

yₙ = C·(-1)ⁿ + n - 1/2。

代入初值 y₀ = 0：C·1 + 0 - 1/2 = 0，得 C = 1/2。所求特解为

**yₙ = (1/2)(-1)ⁿ + n - 1/2**。

检验：y₀ = 1/2 - 1/2 = 0；y₁ = -1/2 + 1 - 1/2 = 0，而 n=0 时右端为 0，y₁+y₀ = 0 成立；n=1 时 y₂ = 1/2 + 2 - 1/2 = 2，y₂+y₁ = 2，右端 2×1 = 2，成立。

**例3** 求 yₙ₊₂ - 5yₙ₊₁ + 6yₙ = 0 的通解；若再给 y₀ = 1，y₁ = 4，求特解。

解：特征方程 λ² - 5λ + 6 = 0，即 (λ-2)(λ-3) = 0，得 λ₁ = 2，λ₂ = 3，是两不等实根。齐次通解为

**yₙ = C₁·2ⁿ + C₂·3ⁿ**。

代入初值：

n=0：C₁ + C₂ = 1
n=1：2C₁ + 3C₂ = 4

两式相减（第二式减第一式乘 2）得 C₂ = 2，进而 C₁ = -1。故特解为

**yₙ = -2ⁿ + 2·3ⁿ**。

（若改为非齐次 yₙ₊₂ - 5yₙ₊₁ + 6yₙ = 3，因 1 不是特征根，可设特解 yₙ* = A；代入得 A - 5A + 6A = 3，即 2A = 3，A = 3/2。通解为 yₙ = C₁·2ⁿ + C₂·3ⁿ + 3/2。）

这三道例题覆盖了一阶常数项、一阶多项式项、二阶齐次三大高频模板。考场上若遇变式，优先判断 f(n) 的类型与是否撞根，再套对应模板，不要从零硬算。

## 五、易错点辨析

1. **差分下标与定义搞错**。Δyₙ = yₙ₊₁ - yₙ，是“向后作差”的向前差分。若把 yₙ₊₁ - yₙ 和 yₙ - yₙ₋₁ 混用，阶数、初值个数会全盘错位。考场统一采用超前形式 yₙ₊₁ + a yₙ = f(n)。
2. **齐次解底数写成 a 而非 -a**。yₙ₊₁ - 2yₙ = 0 的解是 C·2ⁿ，yₙ₊₁ + 2yₙ = 0 的解才是 C·(-2)ⁿ。一个符号决定整题对错。
3. **撞根时漏乘 n**。例如 yₙ₊₁ + yₙ = (-1)ⁿ，a=1，-a=-1，而右端底数 d=-1，有 d+a = 0，必须设 yₙ* = A n (-1)ⁿ；若只设 A(-1)ⁿ，代入后恒为 0，永远定不出 A。判断口诀：看 d+a 是否为 0（一阶）；看 d 或 1 是否为特征根（二阶）。
4. **特解移位算错**。设 yₙ* = A n + B 时，yₙ₊₁* 必须写成 A(n+1) + B。常见错误是只替换下标为 n 的那一项，或忘记常数项中的 +A。
5. **任意常数个数与初值不匹配**。一阶要 1 个初值，二阶要 2 个。只给一个初值就“定出唯一特解”不完整；反之，通解写成不含任意常数也是错的。
6. **复根写成含虚数的解**。特征根为共轭复根时，最终必须化成 rⁿ(C₁ cos nθ + C₂ sin nθ) 的实解形式，数三不接受带虚数单位的答案。
7. **应用题增量方向写反**。“每年衰减 10%”对应 Δyₙ = -0.1 yₙ，即 yₙ₊₁ = 0.9 yₙ；写成 1.1 则完全相反。建模时先用语言写出增量，再翻译成方程。
8. **特解设得过窄**。f(n) 为 k 次多项式时，特解必须设完整的同次多项式 Qₖ(n)，不能只设 A n 而漏掉常数项等低次项。
9. **通解与特解概念混用**。通解必须保留任意常数 C；题目若给初值，要写“所求特解为……”，不要答完通解就交卷。
10. **二阶方程漏掉“降阶特例”**。当 q = 0 时方程不是标准二阶，应降阶处理；若强行套特征方程会得到退化根，通解结构出错。审题时先确认 q ≠ 0。

## 六、考研提示

- **303 数学三**中，本课题直接分值约 4–5 分，多为填空或计算题一小问。频率不高，但命题模板固定——目标是形成条件反射，考场上 3 分钟内拿下。
- **复习优先级**：① 差分定义 Δyₙ = yₙ₊₁ - yₙ → ② 一阶齐次通解 C·(-a)ⁿ → ③ 非齐次三种特解设定（重点是撞根乘 n）→ ④ 二阶特征方程与三种通解 → ⑤ 初值定常数与检验。
- **与前后课题的联系**：方法论与微分方程（线性结构、特征根、待定系数、通解叠加）一一对应，强烈建议和微分方程对照记忆。本课题是微积分模块收尾，不与线性代数交叉。
- **命题趋势**：一阶方程（含简单离散建模）概率最大，二阶齐次次之；数字通常干净利落，考查核心就是“特解形式是否撞根”。把例1、例2 的书写格式练熟，按步骤套模板即可稳定得分。
- **考场策略**：先化标准形，再写齐次，再设特解并代入，最后写通解（有初值则定常数）。每一步单独成行，即使中间算错，步骤分仍可保住。若时间紧张，优先保证一阶题全对，二阶题至少写出特征方程与齐次通解。`,
  quizzes: [
    { id: 'ca-q-07-01a', type: 'short-answer', question: '什么是差分？写出一阶向前差分的定义。', answer: '一阶向前差分定义为 Δyₙ = yₙ₊₁ - yₙ，表示数列从第 n 项到第 n+1 项的增量，是离散情形下对连续导数的类比。', explanation: '差分是差分方程的基本运算。注意下标：Δyₙ 对应 yₙ₊₁ - yₙ，不要与 yₙ - yₙ₋₁ 混淆。' },
    { id: 'ca-q-07-01b', type: 'choice', question: '差分方程 yₙ₊₁ + 3yₙ = 0 的通解是（）', options: ['yₙ = C·3ⁿ', 'yₙ = C·(-3)ⁿ', 'yₙ = C·(-3)ⁿ⁺¹', 'yₙ = C + 3ⁿ'], answer: 'B', explanation: '标准形中 a=3，齐次通解为 yₙ = C·(-a)ⁿ = C·(-3)ⁿ。底数是 -a，符号错误是本题最大陷阱。' },
    { id: 'ca-q-07-01c', type: 'fill', question: '差分方程 yₙ₊₁ - yₙ = 2 的一个特解可设为 yₙ* = ______', answer: '2n', explanation: 'a=-1，1+a=0，属于撞根情形，特解应设为 A n 而非常数 A。代入得 A=2，故特解为 2n（写 An 并定出 A=2 亦可）。' },
    { id: 'ca-q-07-01d', type: 'short-answer', question: '求 yₙ₊₁ - 2yₙ = 3 的通解。', answer: '对应齐次通解为 yₙ = C·2ⁿ。因 1+a = -1 ≠ 0，设特解 yₙ* = A，代入得 -A = 3，A = -3。故通解为 yₙ = C·2ⁿ - 3。', explanation: '按“解齐次→设特解→代入定系数→写通解”四步进行。特解只需一个，C 为任意常数。' },
  ],
  references: ['《高等数学》（同济大学）差分方程附录'],
};


